// Normalise the HubSpot payload into the PRD 20 lead intake event.
// tenant_ref is deliberately NOT sent: PRD 8.2 requires the platform to
// derive the tenant from the service credential, never from the caller.
const body = $json.body ?? $json;
const props = body.properties ?? {};

return {
  json: {
    event_id: body.eventId ?? body.objectId ?? $execution.id,
    source: 'hubspot',
    record_id: String(body.objectId ?? props.hs_object_id ?? ''),
    campaign_ref: $vars.CAMPAIGN_ID,
    contact: {
      name: [props.firstname, props.lastname].filter(Boolean).join(' ') || null,
      phone: props.phone ?? props.mobilephone ?? null,
      email: props.email ?? null
    },
    // The client supplies the consent basis; the agency records it as
    // evidence rather than treating it as verified (PRD 26.1).
    consent: props.consent_basis
      ? {
          basis: props.consent_basis,
          source: props.consent_source ?? 'hubspot_import',
          evidence_ref: props.consent_evidence_ref ?? null,
          captured_at: props.consent_captured_at ?? null
        }
      : null,
    correlation_id: $execution.id
  }
};
